var _0001_auth_default = "-- Better Auth schema (identity + sessions for \"Sign in with Grok\").\n--\n-- Generated by the Better Auth CLI for its Postgres adapter — DO NOT EDIT by\n-- hand. `@/lib/auth/server` runs Better Auth against these tables when\n-- DATABASE_URL is set. The columns are camelCase and MUST stay double-quoted so\n-- Postgres preserves the case Better Auth queries by.\n--\n-- Migrations in this folder are the single source of truth for your schema. They\n-- apply to Neon during the Vercel build (`npm run build`) and to the local\n-- PGLite fallback automatically on startup, so dev matches production. Applied\n-- files are recorded by name in `_migrations` and NEVER run again.\n--\n-- Put YOUR app's schema in NEW ordered files (0002_*.sql, 0003_*.sql, …), never\n-- in this one. For app tables, prefer snake_case and give per-user tables a\n-- `user_id TEXT NOT NULL` column (TEXT, not UUID — the preview dev user id is\n-- the string 'dev-user'), then scope every query to the authenticated user\n-- server-side (see the `neon` + `auth` skills and src/lib/auth/verify.server.ts).\n\ncreate table if not exists \"user\" (\n  \"id\" text not null primary key,\n  \"name\" text not null,\n  \"email\" text not null unique,\n  \"emailVerified\" boolean not null,\n  \"image\" text,\n  \"createdAt\" timestamptz default CURRENT_TIMESTAMP not null,\n  \"updatedAt\" timestamptz default CURRENT_TIMESTAMP not null\n);\n\ncreate table if not exists \"session\" (\n  \"id\" text not null primary key,\n  \"expiresAt\" timestamptz not null,\n  \"token\" text not null unique,\n  \"createdAt\" timestamptz default CURRENT_TIMESTAMP not null,\n  \"updatedAt\" timestamptz not null,\n  \"ipAddress\" text,\n  \"userAgent\" text,\n  \"userId\" text not null references \"user\" (\"id\") on delete cascade\n);\n\ncreate table if not exists \"account\" (\n  \"id\" text not null primary key,\n  \"accountId\" text not null,\n  \"providerId\" text not null,\n  \"userId\" text not null references \"user\" (\"id\") on delete cascade,\n  \"accessToken\" text,\n  \"refreshToken\" text,\n  \"idToken\" text,\n  \"accessTokenExpiresAt\" timestamptz,\n  \"refreshTokenExpiresAt\" timestamptz,\n  \"scope\" text,\n  \"password\" text,\n  \"createdAt\" timestamptz default CURRENT_TIMESTAMP not null,\n  \"updatedAt\" timestamptz not null\n);\n\ncreate table if not exists \"verification\" (\n  \"id\" text not null primary key,\n  \"identifier\" text not null,\n  \"value\" text not null,\n  \"expiresAt\" timestamptz not null,\n  \"createdAt\" timestamptz default CURRENT_TIMESTAMP not null,\n  \"updatedAt\" timestamptz default CURRENT_TIMESTAMP not null\n);\n\ncreate index if not exists \"session_userId_idx\" on \"session\" (\"userId\");\ncreate index if not exists \"account_userId_idx\" on \"account\" (\"userId\");\ncreate index if not exists \"verification_identifier_idx\" on \"verification\" (\"identifier\");\n";
var _0002_trex_default = "-- TREX training catalog (public read) and per-user training records.\n-- Access model: server functions read the catalog freely.\n-- Profiles, completions, bookmarks, and checkout intents are scoped to the\n-- authenticated user id. There is no client-supplied user id.\n\ncreate table if not exists exercises (\n  id text primary key,\n  slug text not null unique,\n  name text not null,\n  description text not null,\n  target_muscles text not null,\n  equipment text not null,\n  difficulty text not null,\n  premium boolean not null default false,\n  video_url text,\n  thumbnail_url text,\n  instructions text not null,\n  mistakes text not null,\n  beginner_mod text not null,\n  advanced_mod text not null,\n  default_sets integer not null,\n  default_reps integer,\n  default_seconds integer,\n  rest_seconds integer not null,\n  calories_per_min integer not null\n);\n\ncreate table if not exists programs (\n  id text primary key,\n  slug text not null unique,\n  title text not null,\n  description text not null,\n  goal_key text not null,\n  difficulty text not null,\n  duration_days integer not null,\n  equipment text not null,\n  requires text not null default 'none',\n  cover_image text,\n  premium boolean not null default false,\n  sort_order integer not null default 0\n);\n\ncreate table if not exists workouts (\n  id text primary key,\n  program_id text not null references programs (id),\n  day_index integer not null,\n  title text not null,\n  description text not null,\n  duration_min integer not null,\n  difficulty text not null,\n  goal text not null,\n  equipment text not null,\n  base_calories integer not null,\n  free_preview boolean not null default false,\n  unique (program_id, day_index)\n);\n\ncreate index if not exists workouts_program_idx on workouts (program_id, day_index);\n\ncreate table if not exists workout_exercises (\n  workout_id text not null references workouts (id) on delete cascade,\n  exercise_id text not null references exercises (id),\n  position integer not null,\n  sets integer not null,\n  reps integer,\n  seconds integer,\n  rest_seconds integer not null,\n  primary key (workout_id, position)\n);\n\ncreate table if not exists profiles (\n  user_id text primary key,\n  goal text,\n  experience text,\n  training_days integer,\n  equipment text,\n  onboarding_completed boolean not null default false,\n  current_program_id text,\n  next_program_id text,\n  plan_reason text,\n  subscription_status text not null default 'free',\n  subscription_plan text,\n  subscription_expires_at timestamptz,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists completions (\n  id text primary key,\n  user_id text not null,\n  workout_id text not null,\n  program_id text,\n  completed_at timestamptz not null default now(),\n  duration_sec integer not null,\n  calories integer not null,\n  exercises_completed integer not null\n);\n\ncreate index if not exists completions_user_idx on completions (user_id, completed_at desc);\n\ncreate table if not exists bookmarks (\n  user_id text not null,\n  workout_id text not null,\n  created_at timestamptz not null default now(),\n  primary key (user_id, workout_id)\n);\n\ncreate table if not exists checkout_intents (\n  id text primary key,\n  user_id text not null,\n  plan text not null,\n  status text not null,\n  created_at timestamptz not null default now()\n);\n";
